calls:
fetch(`${API}/api/chats`).then(r => r.json()).then((data: any[]) => {
            setChatList(data.map((c: any) => ({ id: c.id, title: c.title || c.id, messageCount: c.messageCount || 0 })));
        }).catch

fetch(`${API}/api/skills`)
            .then(r => r.json())
            .then((data: any[]) => {
                const list: SkillItem[] = [];
                for (const s of data) {
                    list.push({ id: s.id, name: s.name || s.id, category: s.category || "" });
                }
                setSkills(list);
            }).catch

fetch(`${API_BASE}/api/fs/file?path=${encodeURIComponent(filePath)}`, { signal: controller.signal })
        .then(r => {
          if (!r.ok) throw new Error(`HTTP ${r.status}`);
          return r.json();
        })
        .then(data => {
          if (data.error) throw new Error(data.error);
          setContent(data.content ?? "");
          setMeta({ size: data.size ?? 0 });
          setLoading(false);
          setLoadedPath(filePath);
        }).catch

fetch(`${API_BASE}/api/fs/file?path=${encodeURIComponent(filePath)}`, { signal: controller.signal })
